import{_ as r,o as t,c as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/import-export-statistik/export-schultraeger-1.png",l="/bilder/import-export-statistik/export-schultraeger-2-optionen.png",m=JSON.parse('{"title":"Daten für den Schulträger verschlüsselt exportieren","description":"","frontmatter":{"title":"Daten für den Schulträger verschlüsselt exportieren","source_pageid":905,"source_revision":5400},"headers":[],"relativePath":"schild3/import-export-statistik/fuer-schultraeger-verwaltung-export.md","filePath":"schild3/import-export-statistik/fuer-schultraeger-verwaltung-export.md"}'),a={name:"schild3/import-export-statistik/fuer-schultraeger-verwaltung-export.md"};function o(d,e,p,u,h,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="daten-fur-den-schultrager-verschlusselt-exportieren" tabindex="-1">Daten für den Schulträger verschlüsselt exportieren <a class="header-anchor" href="#daten-fur-den-schultrager-verschlusselt-exportieren" aria-label="Permalink to &quot;Daten für den Schulträger verschlüsselt exportieren&quot;">​</a></h1><p>Erstellen Sie den für das Schulträgermodul vorgesehenen Export. Wählen Sie Verschlüsselung und Kennwortverfahren und beachten Sie die getrennte Übermittlung eines individuellen Kennworts.</p><p><a href="/bilder/import-export-statistik/export-schultraeger-1.png"><img src="'+i+'" alt="Starten des Exports an den Schulträger." loading="lazy"></a></p><p><em>Starten des Exports an den Schulträger.</em></p><p>Über <em>Verwaltung ➜ Export</em> ➜ <strong>Für Schulträger</strong> können Sie einen Export für Daten an den Schulträger anstoßen.</p><p><a href="/bilder/import-export-statistik/export-schultraeger-2-optionen.png"><img src="'+l+'" alt="Einstellungen des Schulträger-Exports." loading="lazy"></a></p><p><em>Einstellungen des Schulträger-Exports.</em></p><p>Wählen Sie zuerst ein <strong>Ausgabeverzeichnis</strong>.</p><p>Anschließend können unterschiedliche <em>Optionen</em> festgelegt werden.</p><p><strong>Verschlüsselungsverfahren wählen</strong></p><p>Wählen Sie die Art der Verschlüsselung.</p><ul><li><strong>Daten verschlüsselt mit Standardkenntwort</strong> sorgt dafür, dass die Daten mit dem Schulträgermodul entschlüsselt werden können. In diesem Fall muss kein Kenntwort gesetzt und ausgetauscht werden.</li><li><strong>Daten verschlüsselt mit individuellem Kennwort</strong> lässt Sie ein eigenes Kennwort setzen. Dieses Kennwort muss dann auf sicherem Wege dem Schulträger mitgeteilt werden und darf keinesfalls zusammen mit einer eventuellen E-Mail mit verschickt werden, über die auch die Daten übermittelt werden. Das Kennwort soll modernen Standards in Länge und der Verwendung von Groß-, Kleinschreibung, Zahlen und Sonderzeichen entsprechen.</li></ul><p>Damit Sie sicher sind, das Kennwort auch so wie gedacht einzutippen, lässt sich bei der Eingabe das <strong>Kennwort anzeigen</strong>.</p><p>Wurde der E-Mail-Versand in SchILD-NRW eingerichtet, lässt sich eine <strong>E-Mailadresse</strong> angeben, an welche der Export direkt versandt wird.</p><p>Schlussendlich wählen Sie, welche Daten exportiert werden sollen:</p><ul><li><strong>Alle Schüler</strong> exportiert die komplette Schule.</li><li><strong>Nur Schüler, die in der aktuellen Auswahl enthalten sind</strong> exportiert die links angezeigten Schüler. Diese werden vor Aufrufen des Exportfensters über den Reiter <em>Schüler</em> gefiltert.</li></ul><p><strong>Export starten</strong> speichert eine Datei <em>[Schulnummer].zip</em> in das angegebene Verzeichnis.</p><p>Diese kann mit dem verwendeten Passwort beziehungsweise über das Schulträgermodul entpackt werden.</p><p>Das Format entspricht den Schnittstellendateien und kann in einem Tabellenkalkulationsprogramm weiterverarbeitet werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%BCr_Schultr%C3%A4ger_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5400.</p>',21)])])}const S=r(a,[["render",o]]);export{m as __pageData,S as default};
